    setRemotePrivilegeDialog(null)
    setRemotePermissionError(null)
    setIsRemoteLoading(false)
    setPreviewFile(null)
    setPreviewContent('')
    setSelectedDbTable(null)
    setSelectedDbColumn(null)
    setTableColumns([])
